contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        // Seed the pot so that the payout branch, if it occurs, is observable.
        c.play{value: 10}();

        uint balBefore = address(c).balance;
        uint potBefore = c.pot();

        // Force a specific state transition: after this call, if no revert,
        // the pot must be either unchanged (random != 0) or reset to 0 (random == 0),
        // and the contract's balance cannot increase without a matching deposit pot increase.
        c.play{value: 10}();

        uint balAfter = address(c).balance;
        uint potAfter = c.pot();

        // General rule: any successful play() with TICKET_AMOUNT either leaves pot
        // unchanged and increases contract balance by 10, or resets pot to 0 and
        // decreases contract balance by potBefore - 1 (the fee is retained).
        // Equivalently: potAfter is either potBefore or 0, and the balance delta
        // is exactly 10 - (potBefore + 10 - potAfter) + 1 when a payout occurs.
        assert(
            (potAfter == potBefore && balAfter == balBefore + 10) ||
            (potAfter == 0 && balAfter == balBefore - potBefore - 10 + 1 - (potBefore + 10 - (potBefore + 10)) )
        );
    }

    receive() external payable {}
}

